const GLOSSARY_TERMS = [
  { term: "ACV (Actual Cash Value)", def: "The fair market value of a vehicle immediately before the loss, considering depreciation. Used to settle total loss claims." },
  { term: "ADAS", def: "Advanced Driver Assistance Systems. Cameras, sensors, and radar systems (e.g., Tesla Autopilot). Require calibration after any repair involving the windshield, bumpers, or front/rear sensors." },
  { term: "Adverse Carrier", def: "The insurance company representing the at-fault party in a third-party claim." },
  { term: "Argyle", def: "Whip's TNC trip status verification tool. Used to confirm which rideshare period a driver was in at the time of loss." },
  { term: "BI (Bodily Injury)", def: "Coverage for injuries sustained by third parties in an accident where our driver is at fault. Includes medical bills, lost wages, pain and suffering." },
  { term: "Claimant", def: "A third party making a claim against our insured driver. Not the same as the insured (member)." },
  { term: "Contributory Negligence", def: "Legal doctrine in MD, VA, and DC: if the claimant is even 1% at fault, they recover nothing. Strict standard — document carefully." },
  { term: "CSL (Combined Single Limit)", def: "A single policy limit covering both BI and PD combined, rather than separate per-person/per-occurrence limits. Whip's P2/P3 coverage is $1M CSL." },
  { term: "Deductible", def: "The amount the insured pays out-of-pocket before insurance coverage applies. Whip's standard deductible is $2,500." },
  { term: "Demand Letter", def: "A formal written request for payment of damages. Starts the clock on response deadlines. Must include liability basis, damages, and a response deadline." },
  { term: "Diary", def: "The scheduled follow-up date for a claim file. Every open file must have an active diary. Missing diaries = missed deadlines." },
  { term: "DV (Diminished Value)", def: "The reduction in a vehicle's market value after it has been in an accident and repaired. Third parties may claim DV in addition to repair costs." },
  { term: "FNOL", def: "First Notice of Loss. The initial report of an accident or incident. Whip's FNOL form is at drivewhip.com/rideshare/accident/." },
  { term: "Klutch", def: "Whip's commercial auto insurance carrier. Provides P2/P3 coverage ($1M CSL). Policy numbers follow the format [STATE]000S0137." },
  { term: "LOR (Letter of Representation)", def: "A letter from an attorney stating they represent a claimant. Once received, all communication must go through the attorney — not the claimant directly." },
  { term: "LOU (Loss of Use)", def: "Compensation for the time a claimant's vehicle is out of service due to the accident. Calculated as rental rate × days of repair." },
  { term: "Metrocars", def: "Whip's rental fleet program. Vehicles rented through Metrocars are covered under the Metrocars policy, not Klutch." },
  { term: "PD (Property Damage)", def: "Coverage for damage to third-party property (vehicles, structures, etc.) caused by our driver." },
  { term: "Period 0", def: "App off. Driver's personal auto policy is primary. Whip has no coverage obligation." },
  { term: "Period 1", def: "App on, no ride accepted. Contingent liability coverage: $50k/$100k BI, $25k PD. Applies only if driver's personal policy denies." },
  { term: "Period 2", def: "Ride accepted, en route to pickup. Full Klutch commercial policy applies. $1M CSL. Whip is primary." },
  { term: "Period 3", def: "Passenger on board. Full Klutch commercial policy applies. $1M CSL. Whip is primary." },
  { term: "PIP (Personal Injury Protection)", def: "No-fault coverage that pays the insured's medical bills regardless of fault. Required in FL, MA, PA, NJ, NY." },
  { term: "Pro-Rata", def: "Method of calculating the earned/unearned portion of a premium based on the number of days the policy was in force." },
  { term: "Reserves", def: "Money set aside to pay a claim. Must be set accurately and updated as the claim develops." },
  { term: "Snapsheet", def: "Whip's primary claims management system (CRM). All claims filed after Oct 27, 2025 are in Snapsheet." },
  { term: "SOL (Statute of Limitations)", def: "The deadline to file a lawsuit. Varies by state and claim type. Missing the SOL bars the claim entirely." },
  { term: "Subrogation", def: "The right to recover money paid out on a claim from the at-fault third party or their insurer." },
  { term: "TNC (Transportation Network Company)", def: "A rideshare company (Uber, Lyft, Whip). TNC coverage rules apply based on which period the driver was in at the time of loss." },
  { term: "Total Loss", def: "When the cost to repair a vehicle exceeds its ACV (or a state-defined threshold). Settled at ACV minus deductible." },
  { term: "UM/UIM (Uninsured/Underinsured Motorist)", def: "Coverage that pays when the at-fault driver has no insurance or insufficient insurance. Required in most Whip operating states." },
];

const TOS_SECTIONS: { num: number; title: string; body: string }[] = [
  { num: 0, title: "Preamble", body: "Effective: 28 August 2025 Whip Incorporated, its subsidiaries, affiliates, parents, and related companies (\u201cWhip\u201d, \u201cWhip\u201d, \u201cwe\u201d, or \u201cus\u201d), provide a service that allows eligible and approved individuals with active Whip membership agreements (\u201cMembers\u201d or \u201cyou\u201d and collectively with Whip, the \u201cparties\u201d) to reserve and rent Whip vehicles, including their equipment, features, and accessories (\u201cVehicles\u201d). BOTH YOU AND WHIP AGREE, WITH THE LIMITED EXCEPTIONS NOTED BELOW, TO RESOLVE ALL DISPUTES, INCLUDING WITH WHIP\u2019S THIRD PARTIES WORKING ON COLLECTIONS, EVALUATIONS, AND PROCESSING OF PERSONSAL INFORMATION THROUGH BINDING INDIVIDUAL ARBITRATION. BINDING INDIVIDUAL ARBITRATION MEANS THAT YOU AND WHIP ARE EACH WAIVING THE RIGHT TO A JURY TRIAL OR TO PARTICIPATE IN A CLASS ACTION IN THE EVENT OF A DISPUTE. The website located at\u00a0www.drivewhip.com, the services offered on the website, emails, communication software, and other tools used to communicate with Whip (the \u201cPlatform\u201d) contain copyrighted work belonging to Whip. \u00a0These Terms of Service, and all of the policies, guidelines, rules, and agreements included through our Platform or through our physical locations (the \u201cAgreement\u201d) collectively create the legally binding terms and conditions on which we offer you access to and use of our vehicles, and services, which include the use of the Platform, products, and services (collectively, the \u201cServices\u201d). By using the Platform or Services, you agree to be bound by the Agreement. In using our Services, you also agree to abide by all local, state, or federal laws and regulations.\u00a0\u00a0IF, FOR ANY REASON, YOU DO NOT AGREE TO THESE TERMS, PLEASE STOP USING THE SERVICES IMMEDIATELY. The Agreement is also for the express benefit of Whip\u2019s representatives, trustees, directors, officers, shareholders, subsidiaries, employees, attorneys,\u00a0and agents. If, and to the extent, an action of any kind is brought against any such person or entity on account of our Services or any communications and interactions with Whip such persons or entities shall have all of the protections afforded by this Agreement, including any dispute resolution procedure. BY ACCESSING OR USING OUR SERVICES, YOU ARE PERSONALLY ACCEPTING THIS AGREEMENT, AND YOU REPRESENT AND WARRANT THAT YOU HAVE THE RIGHT, AUTHORITY, AND CAPACITY TO ENTER INTO THESE TERMS.\u00a0 YOU FURTHER REPRESENT THAT YOU ARE AT LEAST 25 YEARS OF AGE AND THAT YOU ARE NOT A PERSON BARRED FROM RECEIVING OUR SERVICES UNDER THE LAWS OF THE UNITED STATES OR ANY OTHER APPLICABLE JURISDICTION." },
  { num: 1, title: "1. Your Use of Our Services", body: "You may access portions of our Platform without registering for a membership. However, you will be required to become a member to access all of our features. You are responsible for maintaining the confidentiality of your information used to create a membership, and you are fully responsible for all activities that occur under your membership. Please immediately notify us of any unauthorized use of your account or any other breach of security. If you interact with us or with third-party service providers, you agree that all information that you provide will be accurate, complete, and current. We reserve the right at any time to modify or discontinue, temporarily or permanently, our Services with or without notice. You agree that we shall not be liable to you or to any third party for any modification, suspension or discontinuance of our Services." },
  { num: 2, title: "2. Member Accounts", body: "To fully use the Services, you must create a member account (\u201cMember Account\u201d) by providing certain complete and accurate information and documentation, including without limitation, your name, date of birth, a valid driver\u2019s license, an email, a certification that you have passed a background check with a transportation network company (\u201cTNC\u201d), and other identifying information that we may request to verify your Member Account. When you set up a Member Account, you hereby agree, in accordance with the Fair Credit Reporting Act and applicable consumer reporting laws, as applicable, to allow Whip to obtain and review some or all of the following: your personal motor vehicle reports, your credit report, your auto insurance score, and a background check, which may include a criminal background check (\u201cBackground Checks\u201d).You also give your permission for Whip to re-pull, refresh or otherwise reinitiate any element of the Background Checks at any time during which your Member Account is active.\u00a0 You also agree to provide any further necessary authorizations to facilitate our access to such records of Background Checks during the term of the Agreement. Whip reserves the right to decline, restrict or otherwise take action against you and your Member Account based on any information included in any such Background Check, including for any breach of the Agreement and/or our Services. Whip may terminate or restrict your Member Account for any or no reason at any time. \u00a0If adverse action is taken based on the result of any element of the Background Check then, upon your request, we will provide information on where we received the information.\u00a0 Whip may provide without notice any information necessary to insurance companies or law enforcement authorities to assist in the filing of a stolen car claim, insurance claim, vehicle repossession, or legal action." },
  { num: 3, title: "3. Membership Term", body: "This Agreement shall commence on the Start Date & Time stated in the Vehicle Membership Agreement and shall remain in full force and effect until the Vehicle is returned to Whip for so long as the Member continues to make timely membership payments. Member must return the Vehicle on or before the last paid for date. If the Vehicle is not returned within 72 hours (or other such time as required by local law) after the last paid membership date, then, in addition to the additional costs noted below , Whip may: (i) report the Vehicle as stolen to law enforcement authorities and seek prosecution for theft, (ii) take action to repossess the Vehicle, (iii) take any legal action necessary to protect its rights, and (iv) report the loss to one or more credit agencies and or national stolen car databases. Member\u2019s use and possession of the Vehicle may be terminated at any time by Whip in its sole discretion, without notice and without the requirement of legal process. Upon expiration or termination of the Membership at any time, Member shall immediately return the Vehicle. Member agrees to return the Vehicle in the same condition that the Member received the Vehicle. a.\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0 Vehicles are reserved and paid for in advance on a weekly basis.\u00a0 Returns will be pro-rated on a daily basis per 24 hour period. b.\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0 Whip, our Vehicle financer, or supplier, (\u201cSupplier\u201d), own the Vehicle. You do not own the Vehicle and You acquire no ownership interest in any Vehicle or other items contained in the Vehicle. c.\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0 We may add or remove available Vehicles in our sole discretion. We do not guarantee that any Vehicle will be available to you. Your right to use any Vehicle is subject to Vehicle availability, your continued eligibility, and to the terms of this Agreement. d.\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0 We will require direct access to the Vehicle to contact the Vehicle directly if an emergency occurs or for other business reasons as permitted by law. e.\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0 Your membership allows you to access the Vehicle as long as your membership is current on payments and active. f.\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0 When you book a reservation, we may pre-authorize a charge to your payment method on file in the amount of your deposit and estimated total usage fees (the \u201cPre-Authorization Charge\u201d) and request that you complete a credit card authorization form. If you do not complete the credit card authorization form or your payment method rejects this Pre-Authorization Charge, your reservation will be cancelled. g.\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0 Before the Start Date & Time, you will receive a message indicating when you will receive access to the Vehicle. You must have the mobile device you used to create your Membership Account inside the Vehicle to drive. Your mobile device must be powered and fully functioning to access and start the Vehicle and to end your Vehicle access. h.\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0 You should return the Vehicle to the same location from where you picked it up, unless otherwise directed by Whip. Leaving the Vehicle somewhere other than where you picked it up may result in late fees or other charges." },
  { num: 4, title: "4. Membership Price", body: "The Weekly Membership Fee shall be paid weekly with the first payment due and payable on the Start Date & Time, and subsequent payments occurring every seven days after the Start Date & Time until Member has returned the Vehicle. All payments shall be made by credit card, debit card, or Zelle and made payable to Whip at 14670 Southlawn Lane, Rockville, Maryland 20850 or through the payment portal on the Whip website. No personal checks and/or money orders will be accepted. Member shall be required to keep a valid credit or debit card on file and only use that card to pay the Weekly Membership Fee during the Term of this Agreement. Credit cards must be in the name of the Member.\u00a0 If you update your payment method, you must complete a new credit card authorization form to continue your Membership.\u00a0 Additional costs may include: a.\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0 Failure to pay the Weekly Membership Fee when due may incur a $25 fee. b.\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0 If any payments are not made when due, previous payment methods may be used to complete any missed payment. c.\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0 Member is solely responsible for paying all fees related to the Vehicle, including, but not limited to, gas, tolls, speeding violations, red light violations, parking violations, or other violations as may be required. d.\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0 Member will incur a $25 administrative fee per invoice for any tickets, citations, violations, or infractions that occur during the term of this Agreement. e.\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0 Failure to contact the billing department within 24 hours of a missed payment can result in termination of the Agreement and other rights and remedies provided by this Agreement. f.\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0 Any other fees listed in the Rental Management, Billing, Policies & Terms, or Accidents & Protection Plan sections of the website." },
  { num: 5, title: "5. Additional Charges", body: "Member shall pay all other charges due under this Agreement upon the return of the Vehicle, including but not limited to: a\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0 charges for optional services selected by the Member, such as a Damage Fee Forgiveness; b.\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0 costs associated with damage to, repair of, or loss of the Vehicle, including without limitation, the loss of use, diminution of the Vehicle\u2019s value caused by the damage or repair, administrative and legal fees for claim processing; c. \u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0 all fines, penalties, traffic and/or parking violations, toll fees, repossession, court costs, towing and impound charges, repair costs, and other associated third-party costs incurred; d. \u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0 all expenses related to Member\u2019s failure to return the Vehicle, including without limitation, costs of locating and recovering the Vehicle; e. \u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0 1.5% interest per month (or the maximum allowed by law) for any past due amount ; f. \u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0 all costs incurred to collect unpaid amounts due, including debt collection agency, attorney, or other third-party costs; g. \u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0 the greater of $25 or the maximum amount allowed by law if Member\u2019s payments are stopped, rejected for insufficient funds, or for any other reason the payment from Member is dishonored. h.\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0 a fee of $100 for cleaning or the first smoking offense. Any other smoking offenses will terminate the Agreement. Member is responsible for maintaining the cleanliness of the vehicle and ensuring that no occupants smoke in the Vehicle. i.\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0 Member shall be solely responsible for any and all fees incurred in restoring the Vehicle to the same condition as it was delivered to Member, including the costs to repair any excessive wear and tear. j.\u00a0 \u00a0 \u00a0 \u00a0 \u00a0 \u00a0 \u00a0Member may be responsible for up to $500 per tow or roadside assistance event when the need for service is not caused by a mechanical failure of the vehicle, including but not limited to situations resulting from driver use or negligence (e.g., lockouts, running out of fuel, misuse of the vehicle, etc.). If the vehicle becomes inoperable due to a verified mechanical malfunction not caused by the Member\u2019s use or neglect, Whip will cover the full cost of the tow and related roadside assistance. k.\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0 Member may be subject to additional deposits during the Term, in addition to the Initial Deposit. l. \u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0 Any other fees listed in the Rental Management, Billing, Policies & Terms, or Accidents & Protection Plan sections of the website." },
  { num: 6, title: "6. Member Obligations", body: "Member represents, warrants, and covenants that: a.\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0 Member has and will maintain a valid driver\u2019s license during the duration of the Membership. b.\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0 Member shall not drive the Vehicle more than 150 miles away from Whip\u2019s office address without the prior written consent of Whip. c. \u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0 Member will ensure that all occupants wear their seat belt at all times. d. \u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0 Member agrees to maintain the professional appearance of the Vehicle and keep the interior and exterior of the Vehicle clean at all times. e. \u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0 Member may not modify the Vehicle in any way or install or remove any accessories without prior written authorization of the Whip. f. \u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0 Member agrees to lock the Vehicle when it is not in use. g. \u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0 In the event Member is cited for a moving violation while driving the Vehicle, the Member\u2019s driver\u2019s license is suspended or revoked, or the Vehicle is involved in an accident or is stolen or damaged, Member agrees to immediately report such event to the Whip. h.\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0 Member shall comply at all times with the Policies & Terms , as posted on the Whip website." },
  { num: 7, title: "7. Security Deposit", body: "The Security Deposit will be the first money applied to any balance due at the end of the Membership.\u00a0 Member may be responsible for additional fees or charges in excess of the Security Deposit as otherwise stated in this Agreement." },
  { num: 8, title: "8. Authorized Drivers", body: "Only Member is permitted to operate the Vehicle as authorized driver.\u00a0 Operation of the Vehicle by someone other than the Member may subject you to civil and criminal liability.\u00a0 Member is responsible for all loss or damage caused to Vehicle, even if Member is not operating the Vehicle when the damage occurs. Furthermore, Whip may cancel insurance coverage, protection plan eligibility, liability limits, and/or any other benefit offered to the Member in the event of an unauthorized driver. Whip expressly disclaims and waives all liability\u2014civil, financial, or otherwise\u2014for any claims, damages, injuries, losses, or liabilities arising from the use or operation of the Vehicle by any person who is not an authorized driver." },
  { num: 9, title: "9. Insurance", body: "Member acknowledges and agrees that Member may be responsible for the full amount of any liability arising in connection with the Vehicle during the duration of the Agreement.\u00a0 Member\u2019s insurance, when held personally or available through any other recoverable policy, will always be primary.\u00a0 Member understands and agrees that when they are online with or on a trip through a transportation network company (\u201cTNC\u201d), the insurance policy maintained by the TNC is primary.\u00a0 Member will be responsible for loss and/or damage as stated by the applicable TNC\u2019s insurance coverage.\u00a0 When permitted by law, Member waives any claims related to the provision of damage waivers or limits thereto under state law.\u00a0 If the TNC\u2019s coverage does not apply, Whip covers third party liability up to the state minimums.\u00a0 Member is then responsible for any third-party liability in connection with operation of the Vehicle to the extent of such liability incurred is in excess of the minimum financial responsibility limits of the applicable state. Member acknowledges and agrees in the event of any accident, theft or other liability incident involving the Vehicle during the Agreement or at any time upon Whip\u2019s request, Member will provide Whip a copy of the insurance policy covering Member\u2019s use of the Vehicle or which may respond to any automobile liability involving the Vehicle.\u00a0 In the event of an insurance claim, Whip has Power of Attorney over the claim. In the event of any collision through no fault of the Member, Member hereby acknowledges and assigns all monetary property damage rewards, including, but not limited to, diminished value payments, repair payments, rental car reimbursement payments, deductible reimbursement directly to Whip. Member is required to immediately report any vehicle damage or loss to Whip that occur during the Term." },
  { num: 10, title: "10. Protection Plan", body: "You are responsible for any loss or damage to the Vehicle you do not report prior to the Start Date & Time. \u00a0In the event that you identify damage at the Start Date & Time, You should document any damage to the Vehicle by taking a photo of it and emailing it to the help desk prior to accessing the Vehicle. Included in your Membership fee, Whip offers a protection plan designed to limit your financial risk for physical damage to the Vehicle as long as the Vehicle is used safely and in accordance with this Agreement (\u201cProtection Plan\u201d). The Protection Plan is a contractual benefit that limits what you will pay for Vehicle damage or loss up to $1,000 plus applicable taxes (\u201cDamage Fee\u201d). The Protection plan also includes access to 24/7 roadside support. Member may be responsible for up to $500 per tow or roadside assistance event when the need for service is not caused by a mechanical failure of the vehicle, including but not limited to situations resulting from driver use or negligence (e.g., lockouts, running out of fuel, misuse of the vehicle, etc.). The following are excluded from the Protection Plan: non-collision damage (e.g., windshield chips or missing parts, excluding normal wear and tear), all traffic violations, tolls, parking tickets, late vehicle returns, unauthorized use, and any violations of the Agreement.\u00a0 Members remain financially responsible for these costs." },
  { num: 11, title: "11. Damage Fee Forgiveness Program", body: "For an additional weekly payment and uninterrupted compliance with all other terms of the Agreement, you may elect to participate in the Damage Fee Forgiveness Program (\u201cProgram\u201d) in the event of physical damage to the Vehicle. By opting into the Program, you will not be responsible for the Damage Fee in the event of covered physical damage to the Vehicle. For purposes of this Agreement, an \u201cIncident\u201d means any event or occurrence resulting in physical damage to the Vehicle during the rental period. The Program may be used no more than once within any six (6) month period. The applicable six (6) month period shall be measured from the date you elect to enroll in the Program (\u201cEnrollment Date\u201d). If you utilize the Program for an Incident, such use will apply to the then-current six (6) month period. You will not be eligible to use the Program again until a new six (6) month period begins following the expiration of the current period. Any prior use of the Program will count toward this limitation. You may opt out of the Program at any time prior to an Incident. However, if an Incident occurs while you are enrolled in the Program and you elect or utilize the Program in connection with such Incident, you will be required to continue paying the associated weekly fee through the remainder of the applicable six (6) month period, as measured from your Enrollment Date. Upon expiration of the six (6) month period, you may elect to opt out of or re-enroll in the Program. Whip reserves the right to deny use of the Program if you are not in compliance with this Agreement, including failure to promptly and accurately report any vehicle damage." },
  { num: 12, title: "12. Insurance Limits of Liability", body: "Insurance is provided on the Vehicle while you are operating the Vehicle in compliance with the terms of this Agreement. Whip\u2019s automobile liability insurance provides coverage up to the minimum financial responsibility limits required by state law. To the extent such coverage is imposed by law, that coverage will be for the minimum limits required by law. We are liable only up to the maximum amounts under our insurance coverage and only if the Vehicle was being operated by you or a person entitled to insurance coverage under law. You may be liable to us up to the maximum amounts described above and to an injured person for amounts awarded over such maximum amounts. The existing insurance coverage offered with your Membership may not be sufficient.\u00a0 You are encouraged to contact your insurance professional to obtain excess insurance coverage." },
  { num: 13, title: "13. Vehicle Ownership", body: "Member has no ownership rights in the Vehicle. Whip shall at all times retain ownership and title to the Vehicle. Member shall immediately notify Whip in the event the Vehicle is levied, has a lien attached, or is threatened with a lien and/or seizure as a result of Member\u2019s action, inaction, possession, or use of the Vehicle. Member shall indemnify and hold Whip harmless against any and all losses and/or damages caused by such action or inaction." },
  { num: 14, title: "14. Vehicle Condition & Repairs", body: "Upon execution of this Agreement, Member accepts the Vehicle in its \u201cas is\u201d condition and acknowledges that the Vehicle has been inspected, is in good working order and in factory condition. Member agrees to operate the Vehicle in accordance with the vehicle owner\u2019s manual. Member acknowledges and agrees that during the Term of this Agreement, Member is required to return the Vehicle to Whip for routine inspection and maintenance service at no cost to Member at least one (1) time every sixty (60) days or 10,000 miles whichever occurs first. All repairs necessitated by normal wear and tear such as tires, brakes, fluid changes will be of no cost to the Member as long as the repair is performed by Whip or an authorized agent of Whip. Any damage or repairs necessitated as a result of the negligence of the Member (Damage to rims, screws in the tire, undercarriage damage caused by driving over an object) will be charged to the Member. Based upon availability, Whip may provide a replacement vehicle if Vehicle is being repaired or maintained by Whip. Whip shall have the right to inspect the Vehicle at any time without prior notice to Member. In the event that the Vehicle requires maintenance or is damaged in any way, Member shall immediately notify Whip and return the Vehicle to Whip for inspection and repair. All mechanical maintenance and collision repair related to the Vehicle shall only be performed by Whip or a Whip authorized automotive repair facility. Wear and tear shall include, but is not limited to, the following, even if covered by the Member\u2019s personal insurance policy: Cracked, damaged, or tinted glass; dented or damaged body panels, fenders, lights, or paint; missing equipment or accessories that were provided with the Vehicle, without limitation, wheel covers, jack, wheel wrench, and spare tire or regular tires; tires with less than 3mm of tread remaining at lowest point; damage to the interior of the Vehicle, including, but not limited to, dash, seats, floor covering, upholstery, truck liner, and center console (if applicable); or mechanical damage that affects the safe, proper, or lawful operation of the Vehicle, which would include damage that causes the Vehicle to fail a safety inspection in the State where Vehicle is registered. When Member returns the Vehicle for maintenance or inspection once every 60 days as set forth in this Agreement, the Member shall pay the cost of repairs needed as a result of excess wear and tear." },
  { num: 15, title: "15. No Warranty", body: "Member acknowledges that Member has examined the Vehicle prior to taking possession, and that it is in good condition.\u00a0 It is recommended that Member also take accurate pictures of the Vehicle at the beginning and end of the Term to avoid disputes at a later date.\u00a0 YOU ARE TAKING POSSESSION OF THE VEHICLE AND ANY OPTIONAL ACCESSORIES \u201cAS-IS\u201d AND AGREE THAT YOU HAVE HAD AN ADEQUATE OPPORTUNITY TO INSPECT THE VEHICLE AND ANY OPTIONAL ACCESSORIES AND THEIR OPERATION. TO THE FULLEST EXTENT PERMITTED BY LAW, WHIP EXCLUDES ALL WARRANTIES OF ANY KIND RELATED TO THE VEHICLE, ITS PLATFORM OR SERVICES, BOTH EXPRESS AND IMPLIED, , INCLUDING ANY IMPLIED WARRANTY OF MERCHANTABILITY, FITNESS FOR A PARTICULAR PURPOSE, TITLE, QUIET ENJOYMNET, ACCURACY, NON-INFRINGEMENT, OR OTHER WARRANTIES AND CONDITIONS UNDER APPLICABLE LAWS. YOU WILL BE SOLELY RESPONSIBLE FOR ANY DAMAGE TO YOUR COMPUTER SYSTEM AND/OR MOBILE DEVICE(S) AND/OR FOR LOSS OF DATA THAT RESULTS FROM YOUR USE OF OUR PLATFORM AND/OR SERVICES. NO AGENT, EMPLOYEE, OR REPRESENTATIVE OF OURS HAS ANY AUTHORITY TO BIND US TO ANY AFFIRMATION, REPRESENTATION, OR WARRANTY RELATING TO OUR PRODUCTS AND/OR SERVICES OTHER THAN AS SPECIFICALLY PROVIDED HEREIN. WHIP\u00a0MAKES NO REPRESENTATION AND DOES NOT GUARANTEE SUCH THINGS AS QUALITY, SUITABILITY OR RELIABILITY OF THE PLATFORM OR SERVICES, WHICH INCLUDES SUCH THINGS AS THE QUALITY, FUNCTIONALITY, AVAILABILITY OF ANY VEHICLE, OR THAT THE PLATFORM OR SERVICES WILL MEET YOUR REQUIREMENTS OR EXPECTATIONS. WHIP\u00a0DOES NOT REPRESENT OR GUARANTEE THAT THE PLATFORM OR SERVICES WILL BE ERROR FREE, NOR DOES IT REPRESENT OR WARRANTY A PARTICULAR QUALITY, SUITABILITY OR SAFETY. YOU AGREE THAT ANY AND ALL RISK ARISING OUT OF USING THE PLATFORM OR SERVICES REMAINS SOLELY WITH YOU, TO THE EXTENT ALLOWED UNDER ALL APPLICABLE LAW. IF APPLICABLE LAW REQUIRES ANY WARRANTIES, ALL SUCH WARRANTIES ARE LIMITED IN DURATION TO NINETY (90) DAYS FROM THE DATE OF FIRST USE. SOME JURISDICTIONS DO NOT ALLOW THE EXCLUSION OF IMPLIED WARRANTIES, SO THE ABOVE EXCLUSION MAY NOT APPLY TO YOU.\u00a0 SOME JURISDICTIONS DO NOT ALLOW LIMITATIONS ON HOW LONG AN IMPLIED WARRANTY LASTS, SO THE ABOVE LIMITATION MAY NOT APPLY TO YOU." },
  { num: 16, title: "16. Pricing and Product Descriptions", body: "Although we make reasonable efforts to provide accurate pricing information and service descriptions, pricing mistakes, typographical errors, or mistakes on vehicle availability may occur. We reserve the right to correct such mistakes and errors. In the event that a service is listed at an incorrect price or a\u00a0vehicle\u2019s\u00a0availability or description is inaccurate, we have the right, in our sole discretion, to reject any request or to cancel any order placed for that vehicle or service." },
  { num: 17, title: "17. Vehicle Use Restrictions", body: "The following list includes common examples of things that cannot be done with the Vehicle; however, these examples are not intended to be a complete list of all prohibited uses.\u00a0 Whip reserves the right to add restrictions as reasonably necessary to protect itself, its property, others, or the property of others.\u00a0 Member shall not: a. \u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0 operate the Vehicle or permit it to be operated to commit any violation of law; b. \u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0 operate the Vehicle or permit it to be operated for any race, test, or contest; c.\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0 operate the Vehicle or permit it to be operated for the transport of more passengers or goods than the maximum allowable for the Vehicle as determined by the number of seatbelts; d.\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0 operate the Vehicle or permit it to be operated to carry hazardous materials or explosive substances of any kind; e. \u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0 operate the Vehicle or permit the Vehicle to be driven or parked on roadways not regularly maintained, or on any roads, beaches, driveways, or surfaces likely to cause damage to the Vehicle; f.\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0 operate the Vehicle or permit the Vehicle to be driven or parked in unsafe areas or where the Vehicle is likely to be damaged; g. \u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0 \u00a0operate the Vehicle or permit the Vehicle to be operated to push or tow any other vehicle; h. \u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0 transport any animal in the Vehicle (with the exception of animals licensed to to assist persons with disabilities); i. \u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0 allow any person to smoke, take, or use alcohol or illegal drugs in the Vehicle; j.\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0 use the Vehicle as a residence or otherwise live in the Vehicle; k.\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0 operate the Vehicle outside of the United States; and/or l.\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0 perform any repairs on the Vehicle or allow anyone other than an authorized Whip entity or person to perform repairs on the Vehicle." },
  { num: 18, title: "18. GPS and Telematics", body: "Vehicles may include GPS, telematics technology, or vehicle disabling technology and some Members may have telematics capabilities through applications on their mobile phones (\u201cTelematic Devices\u201d).\u00a0 Telematic Devices track vehicle and driver analytics data.\u00a0 Member consents to the data collected by the Telematic Devices and to this data being used consistent with the Whip Privacy Policy, the privacy policy of the vehicle manufacturer, and the privacy policy of the Telematic Device manufacturer or software provider.\u00a0 Member agrees not to tamper with, disable, or remove such Telematics Device for any reason.\u00a0 Member will be held responsible for any damages to or tampering with any Telematics Devices present in the Vehicle. Telematic Devices allow Whip to locate the Vehicle if it is stolen or is being used in violation of this Agreement. By signing this Agreement, Member voluntarily waives any right Member may have to privacy in the location of the Vehicle and authorizes Whip to use the Device to locate the Vehicle at any time, for any reason, and for any other purpose not prohibited by applicable law. Further, Member acknowledges and agrees that Whip may disable the Vehicle without notice to Member upon breach of this Agreement. Any attempt to tamper or remove device will result in termination of the Agreement." },
  { num: 19, title: "19. Third Party Links, Ads, and Other Members", body: "Our Platform may link to other websites and/or display advertisements for third parties (\u201cThird Party Platforms\u201d). You acknowledge and agree that Whip does not control and is not responsible for the availability of Third Party Platforms.\u00a0 Furthermore, Whip does not endorse and is not responsible or liable for any content, advertising, products and/or other materials on or available from such Third Party Platforms. Whip makes no warranties or representations of any kind as to the accuracy, currency, or completeness of any information contained in such Third Party Platforms and shall have no liability for any damages or injuries of any kind arising from such content or information. You further acknowledge and agree that Whip shall not be responsible or liable, directly or indirectly, for any damage or loss caused or alleged to be caused by or in connection with use of or reliance on any such content, goods or services available on or through any such other Third Party Platform. Inclusion of any third party link does not imply an endorsement or recommendation by Whip. When you click or link to a Third Party Platform, the applicable third party\u2019s terms and policies apply." },
  { num: 20, title: "20. Authorization to Contact You", body: "You agree that Whip and its third party service providers may contact you using email, autodialed, prerecorded, or artificial voice calls and text or media messages, at any email or telephone number that you have provided to Whip. You agree that we may contact you to, among other things, (1) discuss your Member Account, including any transactions related to your Member Account; (2) resolve any issues or problems with your account; (3) resolve a dispute; (4) collect any amounts due or past due; (5) inquire about your experience using our Services; (6) as necessary to provide the Services to you; and/or (7) for marketing purposes, including any offers or promotions related to the Services.\u00a0 Your consent is not a condition of receiving property, goods, or services.\u00a0 Whip may monitor or record telephone conversations for quality control, training purposes or for its own protection. By opting-in to short message service (SMS) and/or multimedia message services (MMS) notifications, you agree to receive informational, transactional, and marketing messages from Whip and its third party vendors.\u00a0 Messaging frequency varies. You can cancel these notifications at any time by texting \u201cSTOP\u201d as a reply from the mobile device receiving messages.\u00a0 You may receive a message to confirm that you have been unsubscribed.\u00a0 If you opt out of receiving messages, you understand and acknowledge that you may not receive the full value of our Services.\u00a0 For further support, email us at join@drivewhip.com.\u00a0 Wireless service providers are not liable for delayed or undelivered messages.\u00a0 As always, message and data rates may apply for any messages sent to or from you.\u00a0 Any questions about your text or data plan should be directed to your wireless service provider." },
  { num: 21, title: "21. Default", body: "In the event that Member defaults under this Agreement, this Agreement shall immediately terminate, and the Member shall be required to pay any and all amounts due under this Agreement for the remainder of the Term. Further, upon the occurrence of a Default, Whip may immediately terminate Member\u2019s right to use the Vehicle without notice and repossess the Vehicle, in its sole discretion.\u00a0 Member shall be in default of this Agreement if any of the following occurs (\u201cDefault\u201d): a. \u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0 upon a failure to pay any Member Payments other payments when due under this Agreement; b.\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0 failure to obtain and maintain insurance coverage as required by the Agreement; c.\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0 misrepresentation and/or breach of any of the terms, obligations and conditions of the Agreement; d.\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0 if the Vehicle is repossessed, stolen, seized or towed through no fault of Whip; e.\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0 a bankruptcy, receivership, or insolvency proceeding is initiated by the Member or against the Member; or f.\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0 any part of the Vehicle or Device (as defined below) is tampered, altered, modified, disengaged or otherwise removed." },
  { num: 22, title: "22. Intellectual Property", body: "The name Whip, Whip, the Platform, and all other Whip marks, logos, designs, and phrasing used in connection with our Services are trademarks, service marks, or trade dress of Whip in the United States may not be used without the prior and express written permission of Whip. Other trademarks, service marks, names, and logos used in conjunction with our Services, such as trademarks, service marks, names, or logos associated with third-party organizations, are the intellectual property of their respective owners. You are granted no right or license with respect to any of the foregoing trademarks, service marks, or logos. We hereby grant you a limited, revocable, non-sublicensable, non-exclusive, and non-transferable license to access our Platform solely for a use authorized by this Agreement. You may not otherwise reproduce, distribute, communicate to the public, make available, adapt, publicly perform, link to, or publicly display the Platform or Services or any adaptations thereof unless expressly set forth in these Terms of Service." },
  { num: 23, title: "23. Content You Submit", body: "\u201cUser Content\u201d means any and all information and content that a user submits to us or uses with the Platform (e.g., content in your Member Account, communications with us, etc.).\u00a0 You are solely responsible for your User Content.\u00a0 You assume all risks associated with use of your User Content, including any reliance on its accuracy, completeness or usefulness by us, or third parties, or any disclosure of your User Content that personally identifies you or any third party.\u00a0 You hereby represent and warrant that your User Content does not violate our Acceptable Use Policy (described below).\u00a0 Because you alone are responsible for your User Content, you may expose yourself to liability if, for example, your User Content violates the Acceptable Use Policy.\u00a0 Company is not obligated to backup any User Content, and your User Content may be deleted at any time without prior notice.\u00a0 You are solely responsible for creating and maintaining your own backup copies of your User Content if you desire. You retain ownership of any intellectual property contained in your User Content.\u00a0\u00a0 However, you hereby grant (and you represent and warrant that you have the right, permission, consent, or license to grant)\u00a0 Whip a royalty-free and fully paid, irrevocable, transferable, sublicensable, and non-exclusive perpetual license throughout the universe for use in any and all media whether now known or hereafter devised to use and exploit (including without limitation by reproduction, distribution, public display, adaptation, communication to the public,\u00a0 public performance, prepare derivative works of, and incorporate into other works) any and all User Content that you submit to us or through our Platform. You also waive to the fullest extent permitted by law any and all claims against us related to moral rights in the User Content. In no circumstances will we be liable to you for any exploitation of any User Content that you submit. Whip has no obligation of protecting as proprietary or confidential, express or implied, with respect to any User Content that you submit to us through our Platform, email, telephone, in person, or otherwise, such as any questions, comments, suggestions, feedback, or the like. \u00a0 You agree that you will not submit to us any information or ideas that you consider to be confidential or proprietary.\u00a0 Whip shall be entitled to use, exploit, or disclose (or choose not to use, exploit, or disclose) such User Content at our sole and absolute discretion without any obligation to you whatsoever (i.e., you will not be entitled to any compensation or reimbursement of any kind from us under any circumstances whatsoever). We shall be free to use any ideas, concepts, know-how or techniques contained in any communication from you to us through our Platform, for any purpose whatsoever, including but not limited to,\u00a0developing, manufacturing and marketing products, without further authorization from you and without any compensation to you." },
  { num: 24, title: "24. Acceptable Use Policy.\u00a0\u00a0The following terms constitute our \u201cAcceptable Use Policy\u201d", body: "(a)\u00a0You agree not to use the Platform to collect, upload, transmit, display, or distribute any User Content (i) that violates any third-party right, including any copyright, trademark, patent, trade secret, moral right, privacy right, right of publicity, or any other intellectual property or proprietary right; (ii) that is unlawful, harassing, abusive, tortious, threatening, harmful, invasive of another\u2019s privacy, vulgar, defamatory, false, intentionally misleading, trade libelous, pornographic, obscene, patently offensive, promotes racism, bigotry, hatred, or physical harm of any kind against any group or individual or is otherwise objectionable; (iii) that is harmful to minors in any way; or (iv) that is in violation of any law, regulation, or obligations or restrictions imposed by any third party. (b)\u00a0In addition, you agree not to: (i) upload, transmit, or distribute to or through the Platform any computer viruses, worms, or any software intended to damage or alter a computer system or data; (ii) send through the Platform unsolicited or unauthorized advertising, promotional materials, junk mail, spam, chain letters, pyramid schemes, or any other form of duplicative or unsolicited messages, whether commercial or otherwise; (iii)\u00a0 use the Platform to harvest, collect, gather or assemble information or data regarding other users, including e-mail addresses, without their consent; (iv) interfere with, disrupt, or create an undue burden on servers or networks connected to the Platform, or violate the regulations, policies or procedures of such networks; (v) attempt to gain unauthorized access to the Platform (or to other computer systems or networks connected to or used together with the Platform), whether through password mining or any other means; (vi) harass or interfere with any other user\u2019s use and enjoyment of the Platform; (vi) use software or automated agents or scripts to produce multiple accounts, or to generate automated searches, requests, or queries to (or to strip, scrape, or mine data from) the Platform (provided, however, that we conditionally grant to the operators of public search engines revocable permission to use spiders to copy materials from the Platform for the sole purpose of and solely to the extent necessary for creating publicly available searchable indices of the materials, but not caches or archives of such materials, subject to the parameters set forth in our robots.txt file); (vii) assign or transfer your Member Account to any other entity or person; (viii) continue to use the Services if your Member Account has been suspended or restricted; or (ix) take any action to circumvent the Services. (c) Enforcement.\u00a0 We reserve the right (but have no obligation) to review any User Content, and to investigate and/or take appropriate action against you in our sole discretion if you violate the Acceptable Use Policy or any other provision of this Agreement or otherwise create liability for us or any other person. Such action may include removing or modifying your User Content, terminating your Member Account, and/or reporting you to law enforcement authorities." },
  { num: 25, title: "25. Procedure for Claims of Copyright Infringement", body: "We have adopted a policy, in compliance with the Digital Millennium Copyright Act (\u201cDMCA\u201d), to enable, at our sole discretion, the expeditious removal of infringing material and the termination of repeat infringers\u2019 Member Accounts. If you have a good faith belief that your copyright is being infringed by any content accessible on or through our Platform, please send a notice of claimed infringement, including the information listed below (pursuant to 17 U.S.C. \u00a7 512(c)), to our designated Copyright Agent at: By mail: Whip, Inc., 14670 Southlawn Lane, Rockville, MD 20850 By email: legal@drivewhip.com To be effective, the notice of claimed infringement must include the following required contents: A physical or electronic signature of a person authorized to act on behalf of the owner of an exclusive right that is allegedly infringed; Identification of the copyrighted work on our Platform claimed to have been infringed, or if multiple copyrighted works are covered by a single notification, a representative list of such works; Identification of the material that is claimed to be infringing or to be the subject of infringing activity that is to be removed, or access to which is to be disabled; information reasonably sufficient to permit us to locate the material (providing specific URLs is the best way to help us locate the content quickly); Information reasonably sufficient to permit us to contact the complaining party, such as the address, telephone, fax, and/or an email address at which the complaining party may be contacted; A statement the complaining party has a good faith belief that use of the material in the manner complained of is not authorized by the copyright owner, its agent, or the law; A statement that the information in the notification is accurate, and under penalty of perjury, that the complaining party is authorized to act on behalf of the owner of an exclusive right that is allegedly infringed. Information provided in this legal notice may be forwarded to the person who provided the allegedly infringing content.\u00a0 Please note that, pursuant to 17 U.S.C. \u00a7 512(f), any misrepresentation of material fact (falsities) in a written notification automatically subjects the complaining party to liability for any damages, costs and attorney\u2019s fees incurred by us in connection with the written notification and allegation of copyright infringement." },
  { num: 26, title: "26. Indemnification", body: "Member covenants to defend and indemnify Whip and its members, affiliates, subsidiaries, owners, employees, contractors, and agents (collectively, the \u201cIndemnified Parties\u201d), and save the Whip and Indemnified Parties harmless from and against all threatened claims, claims, actions, damages, liability, judgments, compensation, cost and expenses, (including, but not limited to, attorneys\u2019 fees and disbursements attendant thereto), in connection with any action brought by Member and/or a third party, against the Whip and/or Indemnified Parties, arising from or out of (i) Member\u2019s use of the Platform or Service; (ii) Member\u2019s use, operation and maintenance of the Vehicle; (iii) Member\u2019s breach or threatened breach of any duty, obligation, representation, and/or warranty; or (iv) Member\u2019s failure to comply with any provision of this Agreement; (v) any action or omission by you that causes the Indemnified Parties to be sued by an owner, driver, passenger, or other third party;(vi) you violation of applicable laws or regulations; or (vii) your User Content. You hereby agree that we shall have the sole right and obligation to control the legal defense against any such claims, demands, or litigation, including the right to select counsel of our choice and to compromise or settle any such claims, demands, or litigation with or without your consent." },
  { num: 27, title: "27. Limitation of Liability", body: "IN NO EVENT SHALL WHIP BE LIABLE FOR ANY INDIRECT, SPECIAL PUNITIVE, CONSEQUENTIAL, OR EXEMPLARY LOSS OR DAMAGES, INCLUDING WITHOUT LIMITATION LOST REVENUE, LOST PROFITS, GOODWILL, DAMAGE TO REPUTATION, INJURY, OR INTERRUPTIONS OF SERVICE AND LOST REVENUE, EVEN IF INFORMED OF THE POSSIBILITY OF SUCH DAMAGES.THESE LIMITS EXTEND TO ANY AND ALL POSSIBLE LEGAL CLAIMS AND THEORIES AND WHETHER THE CLAIMED DAMAGES ARE FINANCIAL OR NON-FINANCIAL IN NATURE. WHIP\u00a0SHALL NOT BE LIABLE FOR ANY LIABILITY OR DAMAGE RELATED TO OR ARISING OUT OF YOUR USE OF (OR INABILITY TO USE) THE SERVICES, THE PLATFORM, OR A VEHICLE. TO THE MAXIMUM EXTENT PERMITTED BY LAW, NOTWITHSTANDING ANYTHING TO THE CONTRARY CONTAINED HEREIN, OUR LIABILITY TO YOU FOR ANY DAMAGES ARISING FROM OR RELATED TO THIS AGREEMENT (FOR ANY CAUSE WHATSOEVER AND REGARDLESS OF THE FORM OF THE ACTION), WILL AT ALL TIMES BE LIMITED TO A MAXIMUM OF ONE HUNDRED US DOLLARS (U.S. $100). THE EXISTENCE OF MORE THAN ONE CLAIM WILL NOT ENLARGE THIS LIMIT. IF YOU ARE DISSATISFIED WITH ANY PORTION OF OUR PLATFORM, SERVICES, OR A VEHICLE, YOUR SOLE AND EXCLUSIVE REMEDY IS TO DISCONTINUE USE OF OUR PLATFORM AND/OR SERVICES AND TO IMMEDIATELY RETURN THE VEHICLE. SOME JURISDICTIONS MAY NOT PERMIT CERTAIN LIMITATIONS OF LIABILITY OR DAMAGES. IF ANY COURT DETERMINES THE LAW OF SUCH A JURISDICTION APPLIES, OUR LIABILITY SHALL BE LIMITED TO THE GREATEST EXTENT PERMITTED BY LAW" },
  { num: 28, title: "28. Dispute Resolution", body: "Dispute Resolution.\u00a0Please read this Arbitration Agreement carefully.\u00a0 It is part of your contract with Whip and affects your rights.\u00a0 It contains procedures for MANDATORY BINDING ARBITRATION AND A CLASS ACTION WAIVER. YOU AND WHIP MUTUALLY AGREE TO WAIVE OUR RESPECTIVE RIGHTS TO RESOLUTION OF DISPUTES IN A COURT OF LAW BY A JUDGE OR JURY AND AGREE TO RESOLVE ANY DISPUTE BY ARBITRATION, as set forth below. This agreement to arbitrate is governed by the Federal Arbitration Act. (a)\u00a0Applicability of Arbitration Agreement.\u00a0\u00a0All claims and disputes (excluding claims for injunctive or other equitable relief as set forth below) in connection with the Agreement or the use of the Platform or Service that cannot be resolved informally, including with Whip\u2019s third parties relating to collections, evaluation, or use of personal information, shall be resolved by binding arbitration on an individual basis under the terms of this Arbitration Agreement.\u00a0 Unless otherwise agreed to, all arbitration proceedings shall be held in English.\u00a0 This Arbitration Agreement applies to you and the Company, and to any subsidiaries, affiliates, agents, employees, predecessors in interest, successors, and assigns, as well as all authorized or unauthorized users or beneficiaries of services or goods provided under the Agreement.\u00a0 Whip\u2019s rights and obligations under this arbitration provision shall inure to the benefit of the consumer reporting agency regardless of whether the consumer reporting agency is named as a co-defendant with Whip or named individually in a claim that would otherwise be subject to this arbitration provision if brought against Whip. (b)\u00a0Notice Requirement and Informal Dispute Resolution.\u00a0 Before either party may seek arbitration, the party must first send to the other party a written Notice of Dispute (\u201cNotice\u201d) describing the nature and basis of the claim or dispute, and the requested relief.\u00a0 A Notice to the Company should be sent to:14670 Southlawn Land, Rockville, MD 20850 with copy to legal@drivewhip.com.\u00a0 After the Notice is received, you and the Company may attempt to resolve the claim or dispute informally.\u00a0 If you and the Company do not resolve the claim or dispute within thirty (30) days after the Notice is received, either party may begin an arbitration proceeding.\u00a0 The amount of any settlement offer made by any party may not be disclosed to the arbitrator until after the arbitrator has determined the amount of the award, if any, to which either party is entitled. (c)\u00a0Arbitration Rules.\u00a0 Arbitration shall be initiated through the American Arbitration Association (\u201cAAA\u201d), an established alternative dispute resolution provider (\u201cADR Provider\u201d) that offers arbitration as set forth in this section.\u00a0 If AAA is not available to arbitrate, the parties shall agree to select an alternative ADR Provider.\u00a0 The rules of the ADR Provider shall govern all aspects of the arbitration, including but not limited to the method of initiating and/or demanding arbitration, except to the extent such rules are in conflict with the Agreement.\u00a0 The AAA Commercial Arbitration Rules (\u201cArbitration Rules\u201d) governing the arbitration are available online at\u00a0www.adr.org\u00a0or by calling the AAA at 1-800-778-7879.\u00a0 The arbitration shall be conducted by a single, neutral arbitrator.\u00a0 Any claims or disputes where the total amount of the award sought is less than Ten Thousand U.S. Dollars (US $10,000.00) may be resolved through binding non-appearance-based arbitration, at the option of the party seeking relief.\u00a0 For claims or disputes where the total amount of the award sought is Ten Thousand U.S. Dollars (US $10,000.00) or more, the right to a hearing will be determined by the Arbitration Rules.\u00a0 Any hearing will be held in a location within 100 miles of Rockville, MD, and unless the parties agree otherwise. Any judgment on the award rendered by the arbitrator may be entered in any court of competent jurisdiction.\u00a0 If the arbitrator grants you an award that is greater than the last settlement offer that the Company made to you prior to the initiation of arbitration, the Company will pay you the greater of the award or $2,500.\u00a0 The arbitrator(s) shall not award consequential damages in any arbitration initiated under this Agreement. Each party shall bear its own costs (including attorney\u2019s fees) and disbursements arising out of the arbitration and shall pay an equal share of the fees and costs of the ADR Provider. (d)\u00a0Non-Appearance Based Arbitration.\u00a0 If non-appearance based arbitration is elected, the arbitration shall be conducted by telephone, online and/or based solely on written submissions; the specific manner shall be chosen by the party initiating the arbitration.\u00a0 The arbitration shall not involve any personal appearance by the parties or witnesses unless otherwise agreed by the parties. (e)\u00a0Time Limits.\u00a0 If you or the Company pursue arbitration, the arbitration action must be initiated and/or demanded within the statute of limitations (i.e., the legal deadline for filing a claim) and within any deadline imposed under the AAA Rules for the pertinent claim. (f)\u00a0Authority of Arbitrator.\u00a0 If arbitration is initiated, the arbitrator will decide the rights and liabilities, if any, of you and the Company, and the dispute will not be consolidated with any other matters or joined with any other cases or parties.\u00a0 The arbitrator shall have the authority to grant motions dispositive of all or part of any claim.\u00a0 The arbitrator shall have the authority to award monetary damages, and to grant any non-monetary remedy or relief available to an individual under applicable law, the AAA Rules, and the Agreement.\u00a0 The arbitrator shall issue a written award and statement of decision describing the essential findings and conclusions on which the award is based, including the calculation of any damages awarded.\u00a0 The arbitrator has the same authority to award relief on an individual basis that a judge in a court of law would have.\u00a0 The award of the arbitrator is final and binding upon you and the Company. (g)\u00a0Waiver of Jury Trial.\u00a0 THE PARTIES HEREBY WAIVE THEIR CONSTITUTIONAL AND STATUTORY RIGHTS TO GO TO COURT AND HAVE A TRIAL IN FRONT OF A JUDGE OR A JURY, instead electing that all claims and disputes shall be resolved by arbitration under this Arbitration Agreement.\u00a0 Arbitration procedures are typically more limited, more efficient and less costly than rules applicable in a court and are subject to very limited review by a court.\u00a0 In the event any litigation should arise between you and the Company in any state or federal court in a suit to vacate or enforce an arbitration award or otherwise, YOU AND THE COMPANY WAIVE ALL RIGHTS TO A JURY TRIAL, instead electing that the dispute be resolved by a judge. (h)\u00a0Waiver of Class or Consolidated Actions.\u00a0 ALL CLAIMS AND DISPUTES WITHIN THE SCOPE OF THIS ARBITRATION AGREEMENT MUST BE ARBITRATED OR LITIGATED ON AN INDIVIDUAL BASIS AND NOT ON A CLASS BASIS, AND CLAIMS OF MORE THAN ONE CUSTOMER OR USER CANNOT BE ARBITRATED OR LITIGATED JOINTLY OR CONSOLIDATED WITH THOSE OF ANY OTHER CUSTOMER OR USER. (i)\u00a0Confidentiality.\u00a0 All aspects of the arbitration proceeding, including but not limited to the award of the arbitrator and compliance therewith, shall be strictly confidential.\u00a0 The parties agree to maintain confidentiality unless otherwise required by law.\u00a0 This paragraph shall not prevent a party from submitting to a court of law any information necessary to enforce this Agreement, to enforce an arbitration award, or to seek injunctive or equitable relief. (j)\u00a0Severability.\u00a0 If any part or parts of this Arbitration Agreement are found under the law to be invalid or unenforceable by a court of competent jurisdiction, then such specific part or parts shall be of no force and effect and shall be severed and the remainder of the Agreement shall continue in full force and effect. (k)\u00a0Right to Waive.\u00a0 Any or all of the rights and limitations set forth in this Arbitration Agreement may be waived by the party against whom the claim is asserted.\u00a0 Such waiver shall not waive or affect any other portion of this Arbitration Agreement. (l)\u00a0Survival of Agreement.\u00a0 This Arbitration Agreement will survive the termination of your relationship with Company. (m)\u00a0Emergency Equitable Relief.\u00a0 Notwithstanding the foregoing, either party may seek emergency equitable relief before a state or federal court in order to maintain the status quo pending arbitration.\u00a0 A request for interim measures shall not be deemed a waiver of any other rights or obligations under this Arbitration Agreement. (n) Notwithstanding the above, claims made by the Whip to repossess the Vehicle or for criminal action by the Member may be made in the court of law at any time without the need to pursue arbitration. (o)\u00a0Courts.\u00a0 In any limited circumstances where the foregoing Arbitration Agreement requires the parties to litigate in court, the parties hereby agree to submit to the personal jurisdiction of the courts located within Montgomery County, Maryland for such purpose." },
  { num: 29, title: "29. Electronic Service", body: "In jurisdictions where electronic service is permitted, the parties agree and consent to service of any process, including formal legal process in any legal proceedings, by electronic service, including e-mail, private facsimile, and any other forms of electronic communication to any contact point provided in Member\u2019s Membership profile The parties agree to deem any service by electronic means to be the same as personal service.\u00a0 In jurisdictions where electronic service is not permitted, the parties will be subject to the requirements of the applicable jurisdiction." },
  { num: 30, title: "30. Statute of Limitations", body: "You and Whip agree that regardless of any statute or law to the contrary, any claim or cause of action arising out of or related to this Agreement, our Platform, our Services must be filed within one (1) year after such claim or cause of action arose or be forever barred." },
  { num: 31, title: "31. Release", body: "To the fullest extent permitted by law, you release Whip and its affiliates and subsidiaries, and any of their members, directors, officers, shareholders, employees, representatives, consultants, attorneys, agents, suppliers, distributors, licensees and/or licensors from any and all responsibility, liability, claims, demands, and/or damages (actual and consequential) of every kind and nature (including personal injuries, death, and property damage), known and unknown, arising out of or in any way connected with the following: (i) disputes between Members, including those between you and other Members; (ii) third party sites and services, including content and/or services found on such sites and services; (iii) disputes concerning any use of or action taken using your Member Account by you or a third party; and/or (iv) claims relating to the unauthorized access to any data communications or content stored under or relating to your Member Account, including unauthorized use or alteration of such communications or your content. If you have a dispute with any party who provides advertising or third party services, on or through our Platform or in conjunction with our Services, or with any party who provides any website/application linked to our Platform, your dispute is solely with that\u00a0 third party, and you release Whip from all claims, demands, and damages (direct, incidental, indirect, punitive, statutory, exemplary, expectation, special or consequential) of every kind and nature, known and unknown, arising out of or in any way connected with such dispute. IF YOU ARE A CALIFORNIA RESIDENT, YOU HEREBY WAIVE CALIFORNIA CIVIL CODE \u00a71542 WHICH STATES THAT \u201cA GENERAL RELEASE DOES NOT EXTEND TO CLAIMS WHICH THE CREDITOR DOES NOT KNOW OR SUSPECT TO EXIST IN HIS OR HER FAVOR AT THE TIME OF EXECUTING THIS RELEASE, WHICH IF KNOWN BY HIM OR HER MUST HAVE MATERIALLY AFFECTED HIS OR HER SETTLEMENT WITH THE DEBTOR.\u201d THE LIMITATIONS IN THIS SECTION NEITHER LIMIT NOR ALTER ANY RIGHTS YOU MAY HAVE AS\u00a0A CONSUMER THAT CANNOT BE EXCLUDED UNDER APPLICABLE LAW. You also waive any and all benefits and rights that would otherwise accrue to you by reason of the provisions of any federal or state statute or principle of common law of any state of the United States, or any political entity or nation, province or local law or regulation that may govern this release, which statute, regulation, law or principle provides in substance something similar to California Civil Code \u00a7 1542. You agree not to file any action or lawsuit inconsistent with the foregoing release or this Agreement." },
  { num: 32, title: "32. Notice for California Users", body: "Under California Civil Code Section 1789.3, users of our Platform and Services from California are entitled to the following specific consumer rights notice: The Complaint Assistance Unit of the Division of Consumer Services of the California Department of Consumer Affairs may be contacted in writing at 400 R Street, Suite 1080, Sacramento, California 95814, or by telephone at (916) 445-1254 or (800) 952-5210." },
  { num: 33, title: "33. Electronic Communications & E-Signatures", body: "The communications between you and Whip use electronic means \u2013 whether you use the Platform or our Services, or whether we post notices on the website or communicate with you via email. For contractual purposes, you (a) consent to receive communications from us in an electronic form; and (b) agree that all terms and conditions, agreements, notices, disclosures, and other communications that we provide to you electronically satisfy any legal requirement that such communications would satisfy if it were be in a hardcopy writing. The foregoing does not affect your non-waivable rights. You agree that this Agreement and other agreements between you and Whip, may be signed and delivered via facsimile, electronic mail (including pdf or any electronic signature complying with the U.S. federal ESIGN Act of 2000, Uniform Electronic Transactions Act or other applicable law) or other transmission method and any counterpart so delivered will be deemed to have been duly and validly delivered and be valid and effective for all purposes." },
  { num: 34, title: "34. Notice", body: "Whip may provide notice to you electronically by directing that notice to the email address you have provided to us, or by written notification\u00a0mailed to the last physical address that you have provided. Notice\u00a0shall be deemed effective 48 hours after it is sent (if by email) or posting (if by regular mail)." },
  { num: 35, title: "35. Miscellaneous", body: "This Agreement\u00a0supersedes all prior agreements and understandings concerning the subject matter herein and constitutes the entire agreement between the Whip and the Member. This Agreement may be amended or modified from time to time only pursuant to a written agreement executed by both parties. This Agreement may not be assignable by Member without the prior written consent of Whip. This Agreement, and the application or interpretation thereof, shall be governed exclusively by its terms and by the laws of the State of Maryland. For any action brought under this Agreement, each party agrees to submit to the exclusive jurisdiction of, and agrees that venue is proper in Montgomery County, Maryland. In connection with this Agreement and the transactions contemplated hereby, Whip and Member shall each execute and deliver any additional documents and instruments and perform any additional acts that may be necessary or appropriate to effectuate and perform the provisions of this Agreement and those transactions." },
  { num: 36, title: "36. Power of Attorney", body: "Member hereby appoints Whip as Member\u2019s attorney-in-fact to execute and deliver proofs of claim, receive payments, endorse checks and other documents, and to take actions necessary to pursue insurance claims and recover payments. Member hereby irrevocably appoints Whip as Member\u2019s attorney-in-fact to execute, apply, amend, file, or take necessary action to confirm or perfect Whip\u2019s security interest in the Vehicle. Before distributing recovered payments, if any, to Member, Whip has the right to offset costs and expenses associated with pursuing claims, perfecting title, and recovering payments." },
  { num: 37, title: "37. Waiver", body: "No failure of Whip to exercise or enforce any rights under this Agreement shall act as a waiver of any subsequent breach(es), and the waiver of any breach shall not act as a waiver of any subsequent breach(es). Whip\u2019s acceptance of payment with knowledge of a default by Member shall not constitute a waiver of any breach." },
  { num: 38, title: "38. Severability", body: "In the event any provision of this Agreement is held by a court or other tribunal of competent jurisdiction to be unenforceable, that provision will be enforced to the maximum extent permissible under applicable law, and the other provisions of this Agreement will remain in full force and effect. Upon a determination that any term or other provision is invalid or illegal and is material to this Agreement, the parties shall negotiate in good faith to modify this Agreement to reflect the original intent of the parties as closely as possible." },
  { num: 39, title: "39. Headings", body: "The section headings used in this Agreement are for reference only and shall not be used or relied upon in the interpretation of this Agreement." },
  { num: 40, title: "40. Survival", body: "Any provisions of this Agreement that are necessary for the enforcement of the terms of this Agreement will survive termination." },
  { num: 41, title: "41. Contact Information", body: "14670 Southlawn Lane Rockville, MD 20850 Telephone: 855-861-9401 Email: join@drivewhip.com" },
];

// ── Sub-components ────────────────────────────────────────────────────────────

function MarketCard({ m }: { m: typeof MARKET_DIRECTORY[0] }) {
  const [open, setOpen] = useState(false);
  return (
    <div className="border border-border rounded-xl overflow-hidden">
      <button onClick={() => setOpen(!open)} className="w-full flex items-start justify-between p-4 text-left hover:bg-muted/30 transition-colors">
        <div>
          <p className="text-xs font-mono uppercase tracking-widest mb-1" style={{ color: m.color }}>{m.state}</p>
          <p className="font-bold text-base">{m.city}</p>
          <p className="text-xs text-muted-foreground mt-0.5">{m.address}</p>
        </div>
        <div className="flex items-center gap-1 mt-1 shrink-0">
          <span className="text-xs text-primary">{open ? "Collapse" : "Click to expand →"}</span>
          {open ? <ChevronDown className="h-4 w-4 text-muted-foreground" /> : <ChevronRight className="h-4 w-4 text-muted-foreground" />}
        </div>
      </button>
      {open && (
        <div className="border-t border-border px-4 py-4 bg-muted/10 space-y-3 text-sm">
          {m.towing && (
            <div className="flex gap-3">
              <Truck className="h-4 w-4 text-muted-foreground shrink-0 mt-0.5" />
              <div>
                <p className="text-xs text-muted-foreground uppercase tracking-wide mb-0.5">Towing</p>
                <p className="font-medium">{m.towing}</p>
                {m.towingPOC && <p className="text-xs text-muted-foreground">POC: {m.towingPOC}</p>}
                {m.towingBackup && <p className="text-xs text-muted-foreground">{m.towingBackup}</p>}
              </div>
            </div>
          )}
          {m.onSite && (
            <div className="flex gap-3">
              <Building2 className="h-4 w-4 text-muted-foreground shrink-0 mt-0.5" />
              <div>
                <p className="text-xs text-muted-foreground uppercase tracking-wide mb-0.5">On-Site</p>
                <p className="font-medium">{m.onSite}</p>
              </div>
            </div>
          )}
          {m.claimsImpound && (
            <div className="flex gap-3">
              <Shield className="h-4 w-4 text-muted-foreground shrink-0 mt-0.5" />
              <div>
                <p className="text-xs text-muted-foreground uppercase tracking-wide mb-0.5">Claims / Impound</p>
                <p className="font-medium">{m.claimsImpound}</p>
              </div>
            </div>
          )}
          {!m.towing && !m.onSite && !m.claimsImpound && (
            <p className="text-xs text-muted-foreground italic">Contact data pending — update via Settings.</p>
          )}
        </div>
      )}
    </div>
  );
}

function CopyButton({ text }: { text: string }) {
  const [copied, setCopied] = useState(false);
  return (
    <button onClick={() => { navigator.clipboard.writeText(text).then(() => { setCopied(true); toast("Copied"); setTimeout(() => setCopied(false), 2000); }); }} className="ml-1 text-muted-foreground hover:text-primary transition-colors shrink-0">
      {copied ? <Check className="h-3.5 w-3.5 text-green-500" /> : <Copy className="h-3.5 w-3.5" />}
    </button>
  );
}

